<template>
	<view class="container">
		<!-- 自定义导航栏 -->
		<view class="custom-navbar">
			<view class="navbar-content">
				<view class="nav-left"></view>
				<view class="nav-title">我的订单</view>
				<view class="nav-right"></view>
			</view>
		</view>
		
		<!-- 状态筛选 -->
		<view class="status-tabs">
			<view 
				class="tab-item" 
				:class="{ active: currentTab === index }"
				v-for="(tab, index) in tabs" 
				:key="index"
				@click="switchTab(index)"
			>
				<text>{{ tab.name }}</text>
				<text class="tab-count" v-if="tab.count > 0">({{ tab.count }})</text>
			</view>
		</view>
		
		<!-- 订单列表 -->
		<scroll-view class="order-list" scroll-y>
			<view class="order-wrapper" v-for="order in filteredOrders" :key="order.id" @click="goToDetail(order.id)">
				<!-- 订单头部 -->
				<view class="order-header">
					<text class="order-no">订单号：{{ order.orderNo }}</text>
					<text class="order-time">{{ order.createTime }}</text>
					<view class="status-tag" :class="order.status">
						<text>{{ getStatusText(order.status) }}</text>
					</view>
				</view>
				
				<view class="order-content">
					<view class="user-info">
						<image class="user-avatar" :src="order.userAvatar" mode="aspectFill"></image>
						<view class="user-details">
							<text class="user-name">{{ order.userName }}</text>
							<text class="service-type">{{ order.serviceType }}</text>
						</view>
					</view>
					<view class="order-info">
						<view class="info-item">
							<text class="info-label">医院</text>
							<text class="info-value">{{ order.hospitalName }}</text>
						</view>
						<view class="info-item">
							<text class="info-label">距离</text>
							<text class="info-value">{{ order.distance }}</text>
						</view>
						<view class="info-item">
							<text class="info-label">报酬</text>
							<text class="info-value price">¥{{ order.price }}</text>
						</view>
					</view>
					<view class="appointment-time" v-if="order.status !== 'cancelled'">
						<text class="time-label">预约时间：</text>
						<text class="time-value">{{ order.appointmentTime }}</text>
					</view>
					<view class="cancel-reason" v-if="order.status === 'cancelled' && order.cancelReason">
						<text class="reason-label">取消原因：</text>
						<text class="reason-value">{{ order.cancelReason }}</text>
					</view>
				</view>
			</view>
			
			<!-- 暂无数据 -->
			<view class="empty-state" v-if="filteredOrders.length === 0">
				<image class="empty-icon" src="/static/empty.png" mode="aspectFit"></image>
				<text class="empty-text">暂无{{ tabs[currentTab].name }}订单</text>
			</view>
		</scroll-view>
	</view>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import OrderCard from '@/components/OrderCard.vue'

// 响应式数据
const currentTab = ref(0)
const tabs = ref([
	{ name: '全部', status: 'all', count: 0 },
	{ name: '已接单', status: 'accepted', count: 0 },
	{ name: '进行中', status: 'in_progress', count: 0 },
	{ name: '已完成', status: 'completed', count: 0 },
	{ name: '已取消', status: 'cancelled', count: 0 }
])

const orderList = ref([])

// 计算属性
const filteredOrders = computed(() => {
	if (currentTab.value === 0) {
		return orderList.value
	}
	return orderList.value.filter(order => order.status === tabs.value[currentTab.value].status)
})

// 更新订单数量统计
const updateOrderCounts = () => {
	tabs.value[0].count = orderList.value.length // 全部
	tabs.value[1].count = orderList.value.filter(order => order.status === 'accepted').length // 已接单
	tabs.value[2].count = orderList.value.filter(order => order.status === 'in_progress').length // 进行中
	tabs.value[3].count = orderList.value.filter(order => order.status === 'completed').length // 已完成
	tabs.value[4].count = orderList.value.filter(order => order.status === 'cancelled').length // 已取消
}

// 从本地存储加载已接单的订单
const loadAcceptedOrders = () => {
	const acceptedOrders = uni.getStorageSync('acceptedOrders') || []
	// 直接设置订单列表为已接单的订单
	orderList.value = acceptedOrders.map(order => {
		// 生成统一格式的时间字符串 (yyyy/MM/dd HH:mm)
		let createTime = order.createTime || order.acceptTime
		if (!createTime) {
			const now = new Date()
			const year = now.getFullYear()
			const month = String(now.getMonth() + 1).padStart(2, '0')
			const day = String(now.getDate()).padStart(2, '0')
			const hours = String(now.getHours()).padStart(2, '0')
			const minutes = String(now.getMinutes()).padStart(2, '0')
			createTime = `${year}/${month}/${day} ${hours}:${minutes}`
		}
		
		return {
			...order,
			orderNo: order.orderNo || `PZ${Date.now()}`,
			createTime: createTime,
			distance: order.distance || '未知'
		}
	})
	updateOrderCounts()
}

// 方法定义
const switchTab = (index) => {
	currentTab.value = index
}

const getStatusText = (status) => {
	switch (status) {
		case 'accepted': return '已接单'
		case 'in_progress': return '进行中'
		case 'completed': return '已完成'
		case 'cancelled': return '已取消'
		default: return '未知状态'
	}
}

const goToDetail = (orderId) => {
	uni.navigateTo({
		url: `/subpkg/order/detail?orderId=${orderId}`
	})
}

const viewDetail = (order) => {
	uni.navigateTo({
		url: `/subpkg/order/detail?orderId=${order.id}`
	})
}

const startService = (order) => {
	uni.showModal({
		title: '开始服务',
		content: '确认开始为患者提供陪诊服务？',
		success: (res) => {
			if (res.confirm) {
				// 更新订单状态为进行中
				order.status = 'in_progress'
				// 更新本地存储
				const acceptedOrders = uni.getStorageSync('acceptedOrders') || []
				const orderIndex = acceptedOrders.findIndex(item => item.id === order.id)
				if (orderIndex !== -1) {
					acceptedOrders[orderIndex].status = 'in_progress'
					uni.setStorageSync('acceptedOrders', acceptedOrders)
				}
				updateOrderCounts()
				uni.showToast({
					title: '服务已开始',
					icon: 'success'
				})
			}
		}
	})
}

const completeService = (order) => {
	uni.showModal({
		title: '完成服务',
		content: '确认已完成陪诊服务？',
		success: (res) => {
			if (res.confirm) {
				// 更新订单状态为已完成
				order.status = 'completed'
				// 更新本地存储
				const acceptedOrders = uni.getStorageSync('acceptedOrders') || []
				const orderIndex = acceptedOrders.findIndex(item => item.id === order.id)
				if (orderIndex !== -1) {
					acceptedOrders[orderIndex].status = 'completed'
					uni.setStorageSync('acceptedOrders', acceptedOrders)
				}
				updateOrderCounts()
				uni.showToast({
					title: '服务已完成',
					icon: 'success'
				})
			}
		}
	})
}

const showActions = (status) => {
	return status !== 'completed' && status !== 'cancelled'
}

const getActionType = (status) => {
	if (status === 'accepted') return 'start'
	if (status === 'in_progress') return 'complete'
	return ''
}

const contactPatient = (order) => {
	uni.showActionSheet({
		itemList: ['拨打电话', '发送短信'],
		success: (res) => {
			if (res.tapIndex === 0) {
				// 拨打电话
				uni.makePhoneCall({
					phoneNumber: order.userPhone || '138****8888'
				})
			} else if (res.tapIndex === 1) {
				// 发送短信
				uni.navigateTo({
					url: `/subpkg/chat/chat?userId=${order.userId}`
				})
			}
		}
	})
}

const handleOrderAction = (actionData) => {
	const { type, data: order } = actionData
	if (type === 'start') {
		startService(order)
	} else if (type === 'complete') {
		completeService(order)
	}
}

// 页面加载时初始化
onMounted(() => {
	// 监听订单状态更新事件
	uni.$on('orderStatusUpdated', (data) => {
		const { orderId, status } = data
		const order = orderList.value.find(item => item.id === orderId)
		if (order) {
			order.status = status
			updateOrderCounts()
		}
	})
	
	// 监听接单事件
	uni.$on('orderAccepted', (acceptedOrder) => {
		// 将新接单的订单添加到订单列表
		orderList.value.unshift(acceptedOrder)
		updateOrderCounts()
	})
	
	// 从本地存储加载已接单的订单
	loadAcceptedOrders()
})

// 页面卸载时移除事件监听
onUnmounted(() => {
	uni.$off('orderStatusUpdated')
	uni.$off('orderAccepted')
})
</script>

